(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.035-t*0.5)*8 + Math.cos((y+wy1)*0.025+t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.03+t*0.45)*8 + Math.sin((x+wx1)*0.028-t*0.55)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.7+3)*110, 40+Math.cos(t*0.3)*60, 0.055, 2.1, 1.3],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.65+4)*50, 0.085, 1.8, 0.6]
  ];
  let aS=0, iS=0, cross=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), b=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a*w; iS+=b*w; cross+=a*b*0.5;
  }
  const n=src.reduce((s,v)=>s+v[4],0);
  const act=aS/n, inh=iS/n, crs=cross/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ripple=Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+crs*0.4+ripple)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const fiber=Math.sin(sx*0.08+t*0.7)*Math.sin(sy*0.06-t*0.5)*0.15;
  const blend=reaction*0.6+cell*0.2+fiber*0.2, v=blend*0.5+0.5;
  const pal=[[5,10,42],[10,45,85],[18,90,120],[30,140,135],[120,170,120],[195,185,80],[210,140,65],[190,85,55],[140,40,60],[70,18,45],[5,10,42]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const glow=Math.exp(-Math.abs(reaction)*0.5)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*80)|0)
  ];
}
